diff --git a/deploy/vps-daemons/pr-brain b/deploy/vps-daemons/pr-brain
index 98f4c71d..38baaf3d 100755
--- a/deploy/vps-daemons/pr-brain
+++ b/deploy/vps-daemons/pr-brain
@@ -142,8 +142,14 @@ log() {

 # A gate that runs unattended and tells nobody is indistinguishable from a gate
 # that never ran. Every action this script takes on GitHub is announced.
+TG_DAEMON_NAME="${TG_DAEMON_NAME:-pr-brain}"
 ENV_FILE="${PR_BRAIN_ENV_FILE:-}"
 notify() {
+  if tg_is_quiet; then
+    tg_hold "$1"
+    return 0
+  fi
+  tg_flush_digest
   [[ -n "$ENV_FILE" && -f "$ENV_FILE" ]] || return 0
   local token chat
   token=$(grep -m1 '^TELEGRAM_BOT_TOKEN=' "$ENV_FILE" | cut -d= -f2- | tr -d '"'"'"'\r')
@@ -163,6 +169,10 @@ notify() {
 # taken 21% of the entire Telegram history, and a photo costs more attention than
 # a line of text, not less.
 notify_photo() {
+  if tg_is_quiet; then
+    tg_hold "Screenshot taken: $2"
+    return 0
+  fi
   [[ -n "$ENV_FILE" && -f "$ENV_FILE" ]] || return 0
   [[ -f "$1" ]] || return 0
   local token chat
@@ -180,13 +190,14 @@ notify_photo() {
 # ~/bin/pr-brain), ../lib in the repo (deploy/lib, next to deploy/vps-daemons). deploy/sync-daemons.sh ships them
 # with the daemons, and tests/unit/scripts/sync-daemons.test.ts fails when a file a daemon sources is not in that
 # copy list. Without them there is no pause state, so refuse to run.
+#   tg-quiet.sh     Telegram quiet hours helper
 #   down-state.sh   one Telegram message per pause/resume + redact_secrets (shared with agent-dispatch)
 #   agy-failure.sh  classify_agy_failure: quota | auth | transient | unknown
 #   agy-run.sh      as_antigravity + agy_run: one agy turn, streamed live into ONE Telegram message
 #   ci-state.sh     required_ci_state: what a PR's required CI checks say (shared with agent-dispatch)
 SELF_PATH="$(readlink -f "${BASH_SOURCE[0]}" 2>/dev/null || printf '%s' "${BASH_SOURCE[0]}")"
 SELF_DIR="$(cd "$(dirname "$SELF_PATH")" 2>/dev/null && pwd)"
-for _lib in down-state.sh agy-failure.sh agy-run.sh ci-state.sh; do
+for _lib in tg-quiet.sh down-state.sh agy-failure.sh agy-run.sh ci-state.sh; do
   _lib_path=""
   for _lib_dir in "$SELF_DIR/lib" "$SELF_DIR/../lib"; do
     [[ -f "$_lib_dir/$_lib" ]] && { _lib_path="$_lib_dir/$_lib"; break; }
@@ -309,6 +320,7 @@ if [[ "$DRY_RUN" -eq 0 && "$LIST_ONLY" -eq 0 ]]; then
     fi
   fi
   trap 'rm -rf "$LOCK"' EXIT
+  tg_flush_digest
 fi

 # What the engine needs on PATH. For agy the binary itself lives in the antigravity user's ~/.local/bin and is
diff --git a/tests/unit/scripts/pr-brain-notify.test.ts b/tests/unit/scripts/pr-brain-notify.test.ts
index 1f532e38..c7c862ec 100644
--- a/tests/unit/scripts/pr-brain-notify.test.ts
+++ b/tests/unit/scripts/pr-brain-notify.test.ts
@@ -48,6 +48,7 @@ function sweep(opts: {
   comments?: string;
   /** Sweep a root with no repositories in it. */
   noRepos?: boolean;
+  quietNow?: string;
 }): void {
   const env = {
     PATH: `${bin}:/usr/bin:/bin:/usr/local/bin`,
@@ -66,6 +67,7 @@ function sweep(opts: {
     FAKE_COMMENTS: opts.comments ?? "",
     CLAUDE_CALLS: claudeCalls,
     SENDS: sends,
+    ...(opts.quietNow ? { TG_QUIET_NOW: opts.quietNow } : {}),
   };
   spawnSync("bash", [SCRIPT], { env, encoding: "utf8", timeout: 30_000 });
 }
@@ -285,3 +287,23 @@ describe("pr-brain — Claude is called on demand only", () => {
     expect(telegramSends().filter((m) => /resumed/i.test(m))).toHaveLength(1);
   });
 });
+
+describe("pr-brain — quiet hours and digest", () => {
+  it("holds notifications into queue during quiet hours and flushes as digest after 08:00", () => {
+    // During quiet hours (02:00 IST), sweep produces zero direct curl sends and holds 1 line in queue
+    sweep({ preflight: "ok", quietNow: "02" });
+    expect(telegramSends()).toHaveLength(0);
+    const queueFile = join(home, ".claude", "tg-digest.queue");
+    expect(existsSync(queueFile)).toBe(true);
+    expect(readFileSync(queueFile, "utf8")).toContain("Gate done — oplify-messaging-api#56");
+
+    // On next sweep after 08:00 IST (09:00 IST), flush digest precedes normal send
+    sweep({ preflight: "ok", head: "bbbb2222", quietNow: "09" });
+    const msgs = telegramSends();
+    expect(msgs.length).toBeGreaterThanOrEqual(2);
+    expect(msgs[0]).toContain("🌅 Overnight digest (1 events)");
+    expect(msgs[0]).toContain("Gate done — oplify-messaging-api#56");
+    expect(msgs[1]).toContain("Gate done — oplify-messaging-api#56");
+    expect(existsSync(queueFile)).toBe(false);
+  });
+});
diff --git a/deploy/lib/tg-quiet.sh b/deploy/lib/tg-quiet.sh
new file mode 100644
--- /dev/null
+++ b/deploy/lib/tg-quiet.sh
@@ -0,0 +10,8 @@
+
+  local curr_hour
+  if [[ -n "${TG_QUIET_NOW:-}" ]]; then
+    curr_hour=$(( 10#$TG_QUIET_NOW ))
+  else
+    curr_hour=$(( 10#$(TZ=Asia/Kolkata date '+%H' 2>/dev/null || date '+%H') ))
+  fi
+
